const settings = $('Load Global Settings').first()?.json ?? {};
const request = $('Preview Case Tracking Email Webhook').first()?.json ?? $input.first()?.json ?? {};
const query = request.query ?? request;
const headers = request.headers ?? {};
const clean = (value) => value === null || value === undefined ? '' : String(value).trim();
const truthy = (value) => ['1', 'true', 'yes', 'y', 'on'].includes(clean(value).toLowerCase());
const deriveBaseUrl = (headers, fallback) => {
  const forwardedProto = clean(headers['x-forwarded-proto']);
  const forwardedHost = clean(headers['x-forwarded-host']);
  const host = forwardedHost || clean(headers.host);
  const forwardedPort = clean(headers['x-forwarded-port']);
  if (!host) return fallback;
  const proto = forwardedProto || 'http';
  let authority = host;
  if (forwardedPort && !authority.includes(':')) {
    const isDefaultPort = (proto === 'http' && forwardedPort === '80') || (proto === 'https' && forwardedPort === '443');
    if (!isDefaultPort) authority = authority + ':' + forwardedPort;
  }
  return proto + '://' + authority;
};
const fallbackBaseUrl = clean(settings.n8n_base_url) || 'http://n8n:5678';
const n8nBaseUrl = deriveBaseUrl(headers, fallbackBaseUrl);
const caseId = /^[0-9a-fA-F-]{36}$/.test(clean(query.case_id)) ? clean(query.case_id) : '';
const requestedMode = clean(query.mode).toLowerCase();
const replyToCaseEmailId = /^[0-9a-fA-F-]{36}$/.test(clean(query.reply_to_case_email_id)) ? clean(query.reply_to_case_email_id) : '';
const mode = requestedMode === 'reply' || requestedMode === 'new'
  ? requestedMode
  : (replyToCaseEmailId ? 'reply' : 'new');
const templateKey = clean(query.template_key);
const signatureTemplateKey = clean(query.signature_template_key) || clean(settings.email_signature_template_key) || 'signature';
const returnUrl = clean(query.return_url) || (n8nBaseUrl + '/webhook/case-tracking?view=dashboard');
const deliveryMode = truthy(query.test_mode) || clean(settings.email_delivery_mode) !== 'production' ? 'test' : 'production';
const openTrackingRaw = clean(query.open_tracking_enabled);
const openTrackingRequested = openTrackingRaw === '' ? '' : (truthy(openTrackingRaw) ? '1' : '0');
const errorMessage = !caseId
  ? 'case_id is required.'
  : (mode === 'reply' && !replyToCaseEmailId ? 'reply_to_case_email_id is required for reply mode.' : '');
return [{
  json: {
    case_id: caseId,
    mode,
    reply_to_case_email_id: replyToCaseEmailId,
    template_key: templateKey,
    signature_template_key: signatureTemplateKey,
    to: clean(query.to),
    return_url: returnUrl,
    n8n_base_url: n8nBaseUrl,
    send_url: n8nBaseUrl + '/webhook/send-case-tracking-email',
    delivery_mode: deliveryMode,
    test_recipient: clean(settings.email_test_recipient) || 'steve.short@gmail.com',
    sender_name: clean(settings.email_sender_name) || 'Steve Short',
    reply_to: clean(settings.email_reply_to) || 'members.avondaleltc@gmail.com',
    open_tracking_requested: openTrackingRequested,
    error_message: errorMessage,
  },
}];

const requestInput = $('Resolve Preview Request').first()?.json ?? {};
const contextRow = $('Load Preview Context').first()?.json ?? {};
const message = contextRow.error_message || requestInput.error_message || 'Unable to prepare the preview.';
const returnUrl = requestInput.return_url || '#';
const escapeHtml = (value) => String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\"/g, '&quot;').replace(/'/g, '&#39;');
const html = '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Email preview unavailable</title></head><body><p>' + escapeHtml(message) + '</p><p><a href="' + escapeHtml(returnUrl) + '">Back to case</a></p></body></html>';
return [{ json: { html } }];

const input = $('Resolve Preview Request').first()?.json ?? {};
const context = $('Load Preview Context').first()?.json ?? {};
const parseMaybe = (value, fallback) => {
  if (value === null || value === undefined || value === '') return fallback;
  if (typeof value === 'string') {
    try { return JSON.parse(value); } catch { return fallback; }
  }
  return value;
};
const clean = (value) => value === null || value === undefined ? '' : String(value).trim();
const caseRow = parseMaybe(context.case_row, {}) || {};
const parentEmailRow = parseMaybe(context.parent_email_row, {}) || {};
const parseRecipients = (value) => {
  const parsed = parseMaybe(value, {});
  return parsed && typeof parsed === 'object' ? parsed : {};
};
const parentRecipients = parseRecipients(parentEmailRow.recipients);
const signatureTemplates = Array.isArray(parseMaybe(context.signature_templates, [])) ? parseMaybe(context.signature_templates, []) : [];
const applyTokens = (value) => {
  let rendered = String(value ?? '');
  const tokenMap = {
    '{{case_title}}': clean(caseRow.title),
    '{{case_status}}': clean(caseRow.status),
    '{{case_priority}}': clean(caseRow.priority),
    '{{contact_name}}': clean(caseRow.contact_name),
    '{{contact_email}}': clean(caseRow.contact_email),
    '{{contact_phone}}': clean(caseRow.contact_phone),
    '{{today}}': new Date().toLocaleDateString('en-GB'),
  };
  for (const [token, replacement] of Object.entries(tokenMap)) {
    rendered = rendered.split(token).join(replacement);
  }
  return rendered.trim();
};
const hasHtmlContent = Boolean(clean(context.html_template) || signatureTemplates.some((template) => clean(template.html_template)));
const emailType = hasHtmlContent ? 'html' : 'text';
const normalizeReplySubject = (value) => {
  const base = clean(value).replace(/^((re|fw|fwd)\s*:\s*)+/i, '').trim();
  return base ? 'Re: ' + base : 'Re: Update from Avondale Tennis Club';
};
const extractEmailAddress = (value) => {
  const text = clean(value);
  if (!text) return '';
  const bracketMatch = text.match(/<\s*([^<>\s]+@[^<>\s]+)\s*>/);
  if (bracketMatch) return clean(bracketMatch[1]);
  const emailMatch = text.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
  return emailMatch ? clean(emailMatch[0]) : '';
};
const pickReplyRecipient = () => {
  const explicitRecipient = extractEmailAddress(input.to) || clean(input.to);
  if (explicitRecipient) return explicitRecipient;
  const candidates = clean(parentEmailRow.direction) === 'outgoing'
    ? [parentRecipients.to, parentRecipients.actual_to, parentRecipients.from, parentRecipients.reply_to]
    : [parentRecipients.reply_to, parentRecipients.from, parentRecipients.to, parentRecipients.actual_to];
  for (const candidate of candidates) {
    const value = extractEmailAddress(candidate);
    if (value) return value;
  }
  return extractEmailAddress(caseRow.contact_email) || clean(caseRow.contact_email);
};
const renderedSubject = clean(input.mode) === 'reply'
  ? normalizeReplySubject(clean(parentEmailRow.subject) || clean(context.subject_template) || clean(caseRow.title) || 'Update from Avondale Tennis Club')
  : applyTokens(clean(context.subject_template) || (clean(context.template_key) ? 'Update from Avondale Tennis Club' : ''));
const renderedMessage = applyTokens(emailType === 'html' ? clean(context.html_template) : clean(context.text_template));
const renderedSignatureTemplates = signatureTemplates.map((template) => ({
  template_key: clean(template.template_key),
  template_name: clean(template.template_name || template.template_key),
  rendered_html: applyTokens(clean(template.html_template)),
  rendered_text: applyTokens(clean(template.text_template)),
}));
const requestedSignatureKey = clean(context.signature_template_key) || clean(input.signature_template_key);
const selectedSignature = renderedSignatureTemplates.find((template) => template.template_key === requestedSignatureKey)
  || renderedSignatureTemplates[0]
  || { template_key: '', template_name: '', rendered_html: '', rendered_text: '' };
const renderedSignature = emailType === 'html' ? clean(selectedSignature.rendered_html) : clean(selectedSignature.rendered_text);
const intendedRecipient = clean(input.mode) === 'reply'
  ? pickReplyRecipient()
  : (extractEmailAddress(input.to) || extractEmailAddress(caseRow.contact_email) || clean(input.to) || clean(caseRow.contact_email));
const actualRecipient = input.delivery_mode === 'production' ? intendedRecipient : input.test_recipient;
const openTrackingEnabled = emailType === 'html'
  ? (clean(input.open_tracking_requested) === '' ? '1' : clean(input.open_tracking_requested))
  : '0';
const combinedPreviewHtml = emailType === 'html' ? (renderedMessage + renderedSignature) : '';
const replyParticipant = clean(parentEmailRow.direction) === 'outgoing'
  ? clean(parentRecipients.to || parentRecipients.actual_to || parentRecipients.from)
  : clean(parentRecipients.reply_to || parentRecipients.from || parentRecipients.to);
return [{
  json: {
    case_id: input.case_id,
    case_title: clean(caseRow.title),
    mode: clean(input.mode) || 'new',
    reply_to_case_email_id: clean(parentEmailRow.id) || clean(input.reply_to_case_email_id),
    parent_internet_message_id: clean(parentEmailRow.internet_message_id),
    parent_references_header: clean(parentEmailRow.references_header),
    parent_gmail_thread_id: clean(parentEmailRow.gmail_thread_id),
    parent_subject: clean(parentEmailRow.subject),
    parent_participant: replyParticipant,
    template_key: clean(context.template_key),
    template_name: clean(context.template_name),
    signature_template_key: clean(selectedSignature.template_key),
    signature_template_name: clean(selectedSignature.template_name),
    signature_options: renderedSignatureTemplates,
    return_url: input.return_url,
    send_url: input.send_url,
    delivery_mode: input.delivery_mode,
    sender_name: input.sender_name,
    reply_to: input.reply_to,
    test_recipient: input.test_recipient,
    intended_recipient: intendedRecipient,
    actual_recipient: actualRecipient,
    email_type: emailType,
    rendered_subject: renderedSubject,
    rendered_message: renderedMessage,
    rendered_signature: renderedSignature,
    combined_preview_html: combinedPreviewHtml,
    open_tracking_enabled: openTrackingEnabled,
    open_tracking_supported: emailType === 'html' ? '1' : '0',
    missing_recipient: intendedRecipient ? '' : 'No recipient email is available for this case.',
  },
}];
